import sys as _mbsys; _mbsys.path.insert(0, 'C:\\Users\\Nanja\\MachineBench\\machinebench\\bridge'); import mb_cam as mb
def run(_context):
    import json
    import adsk.core as core

    app = core.Application.get()
    product = app.activeProduct
    setups = product.setups
    setup = setups.item(0)
    ops = setup.operations

    for i in range(ops.count):
        op = ops.item(i)
        print(f"\n=== Operation {i}: {op.name} ===")
        print(f"  Strategy: {op.strategy}")
        print(f"  hasToolpath: {op.hasToolpath}")

        # Get errors
        try:
            errs = list(op.errors)
            print(f"  Errors ({len(errs)}):")
            for e in errs:
                print(f"    - {e.message}")
        except Exception as e:
            print(f"  Error reading errors: {e}")

        # Get tool info
        try:
            tool = op.tool
            if tool:
                print(f"  Tool: {tool.description}")
                print(f"  Tool diameter: {tool.diameter.value:.4f} {tool.diameter.units}")
            else:
                print(f"  Tool: None")
        except Exception as e:
            print(f"  Error reading tool: {e}")

        # Check geometry type
        try:
            geom = op.geometry
            print(f"  Geometry type: {type(geom).__name__ if geom else 'None'}")
            if geom:
                print(f"  Geometry class: {geom.classType}")
        except Exception as e:
            print(f"  Error reading geometry: {e}")

